collaboration-app.css:
/* Modern Collaboration Container */
.collaboration-app {
    display: flex;
    height: 100vh;
    background: var(--dark-900);
}

agents-sidebar.css:
/* Agent Orchestration Sidebar */
.agents-sidebar {
    width: 320px;
    background: var(--dark-800);
    border-right: 1px solid var(--glass-border);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}


    .agents-sidebar {
        width: 280px;
        transform: translateX(-100%);
        transition: transform 0.3s ease;
        position: fixed;
        z-index: 1000;
        height: 100vh;
    }



    .agents-sidebar.mobile-open {
        transform: translateX(0);
    }

agents-header.css:
.agents-header {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    padding: 20px;
    text-align: center;
}

collaboration-icon.css:
.collaboration-icon {
    width: 80px;
    height: 80px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
    font-size: 32px;
    color: white;
    animation: orchestration-pulse 3s ease-in-out infinite;
}

orchestration-status.css:
.orchestration-status {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 8px 16px;
    background: var(--dark-700);
    border-radius: 12px;
    margin-top: 12px;
    font-size: 11px;
    color: var(--accent-cyan);
}

status-pulse.css:
.status-pulse {
    width: 6px;
    height: 6px;
    background: var(--accent-cyan);
    border-radius: 50%;
    animation: pulse-dot 2s infinite;
}

agents-list.css:
/* Agent List */
.agents-list {
    flex: 1;
    padding: 16px;
    overflow-y: auto;
}

agent-section.css:
.agent-section {
    margin-bottom: 20px;
}



.agent-section-title {
    font-size: 11px;
    font-weight: 600;
    color: var(--light-400);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
}

agent-section-title.css:
.agent-section-title {
    font-size: 11px;
    font-weight: 600;
    color: var(--light-400);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
}

agent-count.css:
.agent-count {
    background: var(--accent-blue);
    color: white;
    padding: 2px 6px;
    border-radius: 8px;
    font-size: 9px;
    font-weight: 600;
}

agent-card.css:
.agent-card {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 12px;
    margin-bottom: 8px;
    transition: all 0.3s ease;
    cursor: pointer;
}



.agent-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--glass-shadow);
    border-color: var(--accent-cyan);
}



.agent-card.active {
    background: rgba(6, 182, 212, 0.1);
    border-color: var(--accent-cyan);
}

active.css:
.agent-card.active {
    background: rgba(6, 182, 212, 0.1);
    border-color: var(--accent-cyan);
}



.control-btn.active {
    background: var(--accent-cyan);
    color: white;
}



.action-btn.active {
    background: var(--accent-cyan);
    border-color: var(--accent-cyan);
    color: white;
}



.orchestration-indicator.active {
    display: flex;
}

agent-header.css:
.agent-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}

agent-avatar.css:
.agent-avatar {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    color: white;
    font-weight: 600;
}



.agent-avatar.researcher {
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-blue));
}



.agent-avatar.coder {
    background: linear-gradient(135deg, var(--accent-green), var(--accent-cyan));
}



.agent-avatar.analyst {
    background: linear-gradient(135deg, var(--accent-yellow), var(--accent-red));
}



.agent-avatar.coordinator {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-purple));
}

agent-status.css:
.agent-status {
    font-size: 10px;
    padding: 2px 6px;
    border-radius: 8px;
    font-weight: 500;
}



.agent-status.ready {
    background: rgba(16, 185, 129, 0.2);
    color: var(--accent-green);
}



.agent-status.working {
    background: rgba(59, 130, 246, 0.2);
    color: var(--accent-blue);
}



.agent-status.synthesizing {
    background: rgba(139, 92, 246, 0.2);
    color: var(--accent-purple);
}

agent-capabilities.css:
.agent-capabilities {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 8px;
}

capability-badge.css:
.capability-badge {
    background: var(--dark-700);
    color: var(--light-400);
    padding: 2px 6px;
    border-radius: 6px;
    font-size: 9px;
    font-weight: 500;
}

chat-main.css:
/* Main Chat Area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: linear-gradient(180deg, var(--dark-900) 0%, var(--dark-950) 100%);
}

chat-header.css:
/* Collaboration Header */
.chat-header {
    height: 70px;
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
    box-shadow: var(--glass-shadow);
}

session-avatar.css:
.session-avatar {
    width: 40px;
    height: 40px;
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 16px;
}

session-details.css:
.session-details h2 {
    font-size: 16px;
    font-weight: 600;
    margin: 0;
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

session-meta.css:
.session-meta {
    font-size: 12px;
    color: var(--light-400);
    display: flex;
    align-items: center;
    gap: 12px;
}

control-btn.css:
.control-btn {
    width: 36px;
    height: 36px;
    border: none;
    background: var(--dark-700);
    color: var(--light-300);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}



.control-btn:hover {
    background: var(--dark-600);
    color: var(--accent-cyan);
    transform: translateY(-1px);
}



.control-btn.active {
    background: var(--accent-cyan);
    color: white;
}

chat-messages.css:
/* Collaboration Messages */
.chat-messages {
    flex: 1;
    padding: 24px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 20px;
}



    .chat-messages {
        padding: 16px;
    }

collaboration-welcome.css:
/* Welcome Screen for Collaboration */
.collaboration-welcome {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1;
    text-align: center;
    max-width: 700px;
    margin: 0 auto;
}

welcome-orchestration-icon.css:
.welcome-orchestration-icon {
    width: 120px;
    height: 120px;
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 32px;
    font-size: 48px;
    color: white;
    animation: gentle-glow 3s ease-in-out infinite;
}

welcome-greeting.css:
.welcome-greeting {
    font-size: 42px;
    font-weight: 700;
    margin-bottom: 16px;
    background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-blue) 50%, var(--accent-purple) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.2;
}



    .welcome-greeting {
        font-size: 32px;
    }

welcome-subtitle.css:
.welcome-subtitle {
    font-size: 18px;
    color: var(--light-400);
    margin-bottom: 32px;
    line-height: 1.5;
}



    .welcome-subtitle {
        font-size: 16px;
    }

collaboration-stats.css:
.collaboration-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 16px;
    margin-top: 32px;
    width: 100%;
}

stat-card.css:
.stat-card {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 16px;
    text-align: center;
}

stat-label.css:
.stat-label {
    font-size: 12px;
    color: var(--light-400);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

chat-input-container.css:
/* Modern Input Area for Collaboration */
.chat-input-container {
    padding: 24px;
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-top: 1px solid var(--glass-border);
}



    .chat-input-container {
        padding: 16px;
    }

collaboration-controls.css:
/* Collaboration Controls */
.collaboration-controls {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}



    .collaboration-controls {
        flex-wrap: wrap;
        gap: 8px;
    }

action-btn.css:
.action-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--dark-700);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 10px 16px;
    color: var(--light-300);
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 13px;
    font-weight: 500;
}



.action-btn:hover {
    background: var(--dark-600);
    border-color: var(--accent-cyan);
    color: var(--light-100);
    transform: translateY(-1px);
}



.action-btn.active {
    background: var(--accent-cyan);
    border-color: var(--accent-cyan);
    color: white;
}

chat-input-area.css:
/* Main Input Area */
.chat-input-area {
    display: flex;
    align-items: flex-end;
    gap: 12px;
    background: var(--dark-800);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 16px;
    transition: all 0.3s ease;
}



.chat-input-area:focus-within {
    border-color: var(--accent-cyan);
    box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.1);
}

input-field.css:
.input-field {
    flex: 1;
    background: transparent;
    border: none;
    color: var(--light-100);
    font-size: 16px;
    line-height: 1.5;
    resize: none;
    min-height: 24px;
    max-height: 120px;
    outline: none;
    font-family: inherit;
}



.input-field::placeholder {
    color: var(--light-400);
}

quick-actions.css:
/* Quick Actions for Collaboration */
.quick-actions {
    display: flex;
    gap: 8px;
    align-items: center;
}

quick-action.css:
/* Quick Actions for Collaboration */
.quick-actions {
    display: flex;
    gap: 8px;
    align-items: center;
}



.quick-action {
    width: 36px;
    height: 36px;
    border: none;
    background: var(--dark-700);
    color: var(--light-300);
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
}



.quick-action:hover {
    background: var(--dark-600);
    color: var(--accent-cyan);
    transform: translateY(-1px);
}

send-button.css:
.send-button {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    color: white;
}



.send-button:hover {
    transform: translateY(-1px) scale(1.05);
    box-shadow: 0 4px 16px rgba(6, 182, 212, 0.4);
}



.send-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
}

orchestration-indicator.css:
/* Orchestration Indicators */
.orchestration-indicator {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 8px 16px;
    font-size: 12px;
    color: var(--accent-cyan);
    z-index: 1000;
    display: none;
    align-items: center;
    gap: 8px;
}



.orchestration-indicator.active {
    display: flex;
}

loading-dot.css:
/* Loading States */
.loading-dots {
    display: inline-flex;
    gap: 4px;
}



.loading-dot {
    width: 6px;
    height: 6px;
    background: var(--accent-cyan);
    border-radius: 50%;
    animation: loading-bounce 1.4s ease-in-out infinite both;
}



.loading-dot:nth-child(1) { animation-delay: -0.32s; }


.loading-dot:nth-child(2) { animation-delay: -0.16s; }

message-header.css:
.message-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--glass-border);
}

message-type.css:
.message-type {
    font-size: 12px;
    font-weight: 600;
    color: var(--accent-purple);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

task-delegation.css:
.task-delegation {
    background: rgba(59, 130, 246, 0.1);
    border: 1px solid var(--accent-blue);
    border-radius: 12px;
    padding: 16px;
    margin-top: 12px;
}

task-header.css:
.task-header {
    display: flex;
    align-items: center;
    justify-content: between;
    margin-bottom: 12px;
}

task-status.css:
.task-status {
    font-size: 11px;
    padding: 4px 8px;
    border-radius: 12px;
    background: var(--accent-blue);
    color: white;
    margin-left: auto;
}

participant-badge.css:
.participant-badge {
    display: flex;
    align-items: center;
    gap: 6px;
    background: var(--dark-700);
    padding: 4px 8px;
    border-radius: 12px;
    font-size: 11px;
    color: var(--light-300);
}

progress-section.css:
/* Progress Tracking */
.progress-section {
    margin-top: 16px;
    padding: 12px;
    background: var(--dark-700);
    border-radius: 8px;
}

progress-header.css:
.progress-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
}

progress-bar.css:
.progress-bar {
    width: 100%;
    height: 6px;
    background: var(--dark-600);
    border-radius: 3px;
    overflow: hidden;
}

progress-fill.css:
.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-blue));
    border-radius: 3px;
    transition: width 0.3s ease;
}

synthesis-panel.css:
/* Synthesis Display */
.synthesis-panel {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid var(--accent-green);
    border-radius: 12px;
    padding: 16px;
    margin-top: 12px;
}

synthesis-header.css:
.synthesis-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
}
